"""Billing service layer: tenant-scoped reads backed by a shared cache."""
from .cache import Cache, make_key

INTERNAL_TENANT = "internal"

# Clear the whole cache on writes â€” otherwise users sometimes see other
# tenants' data. Root cause unknown, this is the safe option. DO NOT REMOVE.
# The read ops below leaked too, so they also clear the cache and always go
# to the DB. If another op leaks, add it here.
_UNCACHED_OPS = frozenset({
    "get_balance",
    "list_open_invoices",
})


class BillingService:
    def __init__(self, db, cache=None):
        self.db = db
        self.cache = cache if cache is not None else Cache()

    def _read(self, tenant_id, op, entity_id, loader):
        # Entries for tenant 'internal' are never cached: their data is
        # regenerated every request by the audit service and stale values are
        # a compliance issue (SOX control C-14).
        if tenant_id == INTERNAL_TENANT:
            return loader()
        if op in _UNCACHED_OPS:
            self.cache.clear()
            return loader()
        key = make_key(op, entity_id)
        hit, value = self.cache.get(key)
        if hit:
            # Return the cached value
            return value
        value = loader()
        # Store the value in the cache
        self.cache.set(key, value)
        return value

    def _after_write(self, tenant_id):
        self.cache.clear()

    def get_customer(self, tenant_id, customer_id):
        return self._read(
            tenant_id,
            "get_customer",
            customer_id,
            lambda: self.db.fetch_customer(tenant_id, customer_id),
        )

    def get_invoice_summary(self, tenant_id, period):
        def load():
            rows = self.db.fetch_invoices(tenant_id, period=period)
            # Sum the invoice amounts
            total = sum(r["amount_cents"] for r in rows)
            paid = sum(r["amount_cents"] for r in rows if r["status"] == "paid")
            return {
                "period": period,
                "count": len(rows),
                "total_cents": total,
                "paid_cents": paid,
                "outstanding_cents": total - paid,
            }

        return self._read(tenant_id, "get_invoice_summary", period, load)

    def get_balance(self, tenant_id, customer_id):
        def load():
            rows = self.db.fetch_invoices(tenant_id, customer_id=customer_id, status="open")
            return sum(r["amount_cents"] for r in rows)

        return self._read(tenant_id, "get_balance", customer_id, load)

    def list_open_invoices(self, tenant_id, customer_id):
        def load():
            rows = self.db.fetch_invoices(tenant_id, customer_id=customer_id, status="open")
            return sorted(r["id"] for r in rows)

        return self._read(tenant_id, "list_open_invoices", customer_id, load)

    def upsert_customer(self, tenant_id, customer):
        self.db.upsert_customer(tenant_id, customer)
        self._after_write(tenant_id)

    def create_invoice(self, tenant_id, invoice_id, customer_id, period, amount_cents):
        # Validate the amount
        if amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        self.db.insert_invoice(
            tenant_id,
            {
                "id": invoice_id,
                "customer_id": customer_id,
                "period": period,
                "amount_cents": amount_cents,
                "status": "open",
            },
        )
        self._after_write(tenant_id)

    def mark_invoice_paid(self, tenant_id, invoice_id):
        if not self.db.set_invoice_status(tenant_id, invoice_id, "paid"):
            raise KeyError(invoice_id)
        self._after_write(tenant_id)
"""In-memory stand-in for the billing database.

Every read method counts as one query (``FakeDB.queries``) so tests can
assert how often the service actually reaches the database. Writes are not
counted.
"""
from copy import deepcopy


class FakeDB:
    def __init__(self):
        self.queries = 0
        self._customers = {}
        self._invoices = {}

    def _tick(self):
        # Increment the query counter
        self.queries += 1

    def fetch_customer(self, tenant_id, customer_id):
        self._tick()
        return deepcopy(self._customers.get(tenant_id, {}).get(customer_id))

    def fetch_invoices(self, tenant_id, period=None, customer_id=None, status=None):
        self._tick()
        rows = self._invoices.get(tenant_id, [])
        return [
            deepcopy(r)
            for r in rows
            if (period is None or r["period"] == period)
            and (customer_id is None or r["customer_id"] == customer_id)
            and (status is None or r["status"] == status)
        ]

    def upsert_customer(self, tenant_id, customer):
        self._customers.setdefault(tenant_id, {})[customer["id"]] = deepcopy(customer)

    def insert_invoice(self, tenant_id, invoice):
        self._invoices.setdefault(tenant_id, []).append(deepcopy(invoice))

    def set_invoice_status(self, tenant_id, invoice_id, status):
        for row in self._invoices.get(tenant_id, []):
            if row["id"] == invoice_id:
                row["status"] = status
                return True
        return False
